def _prepare_writable_soc_ap(tmp_dir: pathlib.Path) -> pathlib.Path:
    """准备包含 third_party/install 依赖链接的可构建 soc-ap 源码根目录（兼容只读 Docker 沙箱）。"""
    # 若宿主机工作区已存在 third_party/install 则直接复用，否则在临时目录创建带 /usr/local 链接的副本
    src_soc = WORKSPACE_ROOT / "soc-ap"
    if (src_soc / "third_party/install").exists():
        return src_soc
    soc_copy = tmp_dir / "soc-ap"
    if not soc_copy.exists():
        shutil.copytree(src_soc, soc_copy, ignore=shutil.ignore_patterns(".git", "build*", "runtime", "third_party"))
        tp_dir = soc_copy / "third_party"
        tp_dir.mkdir(parents=True, exist_ok=True)
        install_link = tp_dir / "install"
        if not install_link.exists():
            install_link.symlink_to("/usr/local")
    return soc_copy


def _run_soc_ap_cmake_test(tmp_dir: pathlib.Path, svc_rel: str, target_bin: str) -> Tuple[bool, str]:
    """在临时构建目录中通过 CMake 编译并运行 soc-ap 指定服务的单元测试可执行文件。"""
    # 使用独立构建目录 tmp_dir/<target_bin> 编译并直接执行真实 C++ 单测二进制
    svc_dir = _prepare_writable_soc_ap(tmp_dir) / svc_rel
    bdir = tmp_dir / f"build_{target_bin}"
    cfg = subprocess.run(["cmake", "-S", str(svc_dir), "-B", str(bdir)], capture_output=True, text=True, timeout=60)
    if cfg.returncode != 0:
        return False, f"CMake configure failed for {target_bin}: {cfg.stderr.strip()}"
    bld = subprocess.run(
        ["cmake", "--build", str(bdir), "--target", target_bin, "-j4"], capture_output=True, text=True, timeout=120
    )
    if bld.returncode != 0:
        return False, f"CMake build failed for {target_bin}: {bld.stderr.strip()}"
    exe = subprocess.run([str(bdir / target_bin)], capture_output=True, text=True, timeout=60)
    if exe.returncode != 0:
        return False, f"{target_bin} failed (rc={exe.returncode}): {exe.stderr.strip() or exe.stdout.strip()}"
    return True, exe.stdout


